"""Save the final blog post as dated markdown with front matter."""
from __future__ import annotations

import re
from datetime import datetime
from pathlib import Path

BANNER = (
    "<!-- Generated by crewai-research-content-team (CrewAI + Google Gemini) -->\n"
    "<!-- In mock mode this content comes from a bundled offline mock LLM, not Gemini. -->\n\n"
)


def slugify(text: str, max_len: int = 60) -> str:
    slug = re.sub(r"[^a-z0-9]+", "-", (text or "").lower()).strip("-")
    return (slug[:max_len].rstrip("-")) or "untitled"


def write_post(topic: str, content: str, out_dir: str | Path = "output") -> Path:
    out = Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)
    date = datetime.now().strftime("%Y-%m-%d")
    path = out / f"{date}-{slugify(topic)}.md"
    front_matter = (
        "---\n"
        f"topic: \"{topic}\"\n"
        f"date: {date}\n"
        "pipeline: researcher -> writer (CrewAI sequential)\n"
        "---\n\n"
    )
    path.write_text(front_matter + BANNER + (content or "").strip() + "\n", encoding="utf-8")
    return path
